import test from 'node:test';import assert from 'node:assert/strict';import {create,evaluate,assign,respond,run,policyComparison,TEAMS} from './engine.js';
test('transfers land on receivers and negatives respect their chosen buffer',()=>{const s=create(),r=evaluate(s);assert.equal(r.flows.find(f=>f.from==='delivery'&&f.to==='platform').value,-7*.45);assert.equal(r.outcomes.platform,59-7*.45-3*.45);assert.equal(r.global,Object.values(r.outcomes).reduce((a,b)=>a+b)/4);});
test('changing rewards alone does not change realized outcomes',()=>{const s=create();assert.deepEqual(evaluate(s).outcomes,evaluate({...s,reward:1}).outcomes);assert.notDeepEqual(evaluate(s).rewards,evaluate({...s,reward:1}).rewards);});
test('zero external coupling makes local protection useful globally',()=>{const s={...create(),pressure:0},r=policyComparison(s);assert.equal(r[0].result.global,59);assert.equal(r[1].result.global,59);assert.equal(run(s).status,'stable');});
test('shared rewards can improve the same coupled system, and comparison is repeatable',()=>{const s=create(),r=policyComparison(s);assert.ok(r[1].result.global>r[0].result.global);assert.deepEqual(r,policyComparison(s));for(const t of TEAMS)assert.ok([0,1,2].includes(respond(s).actions[t.id]));assert.throws(()=>assign(s,'sales',4));});
